package TaskB2;
import java.sql.*;
public class SqlInjectionDemo { public static boolean unsafe(Connection c,String id,String pwd)throws SQLException{String sql="SELECT * FROM users WHERE id='"+id+"' AND pwd='"+pwd+"'";try(Statement s=c.createStatement();ResultSet r=s.executeQuery(sql)){return r.next();}} public static boolean safe(Connection c,String id,String pwd)throws SQLException{try(PreparedStatement p=c.prepareStatement("SELECT * FROM users WHERE id=? AND pwd=?")){p.setString(1,id);p.setString(2,pwd);try(ResultSet r=p.executeQuery()){return r.next();}}} public static void main(String[] a)throws Exception{try(Connection c=Task05.Db.connect()){System.out.println("Unsafe bypass="+unsafe(c,"' OR '1'='1' -- ","wrong"));System.out.println("PreparedStatement bypass="+safe(c,"' OR '1'='1' -- ","wrong"));}} }
